SELECT EMPLOYER_NO, BUSINESS_NICKNAME, BUSINESS_ADDRESS, BUSINESS_TEL
FROM "EMPLOYER"
WHERE MEMBER_NO = ${memberNo}

SELECT EMPLOYER_NO, BUSINESS_NICKNAME, BUSINESS_ADDRESS, BUSINESS_TEL, MEMBER_NO
FROM "EMPLOYER"
WHERE EMPLOYER_NO = ${employerNo}

SELECT EMPLOYER_NO
FROM EMPLOYER
WHERE BUSINESS_NICKNAME = #{businessNickname}

SELECT WORKTYPE_NO
FROM EMPLOYER_WORKTYPE
WHERE WORKTYPE_CATEGORY = #{category}
